_SENSITIVE_AUDIT_KEYS = {
    "password",
    "password_hash",
    "token",
    "access_token",
    "refresh_token",
    "secret",
    "api_key",
    "credentials",
}


def _sanitize_audit_value(value, key=None):
    """Redact sensitive fields recursively before writing audits.

    - If a key looks sensitive (password, token, secret etc.) the value
      is replaced with the string "[REDACTED]".
    - Works recursively for dict/list/tuple structures so nested secrets
      won't be accidentally stored in the audit log.
    """
    # Shortcut: if this value is keyed by a sensitive name, redact it.
    if key and key.lower() in _SENSITIVE_AUDIT_KEYS:
        return "[REDACTED]"

    # Recurse into dicts and sequence types to sanitize nested values.
    if isinstance(value, dict):
        return {name: _sanitize_audit_value(item, name) for name, item in value.items()}
    if isinstance(value, (list, tuple)):
        return type(value)(_sanitize_audit_value(item) for item in value)
    return value


