    # -------------------------------------------------
    # Authentication
    # -------------------------------------------------
    def authenticate(self, username, password):
        """function authenticate - TODO: add description.
        Generated: 2026-08-01T21:49:18.295802Z
        """
        try:
            user = self.users.find_one({"username": username})
            if not user:
                logger.info(f"Login failed: user '{username}' not found")
                return None

            stored_hash = user.get("password_hash")
            if not stored_hash:
                logger.error(f"User '{username}' has no password_hash field")
                return None

            # Use bcrypt's secure comparison to verify the password hash.
            if bcrypt.checkpw(password.encode(), stored_hash.encode()):
                logger.info(f"User '{username}' authenticated successfully")
                return user

            logger.info(f"Login failed: incorrect password for '{username}'")
            return None

        except Exception as e:
            logger.error(f"Authentication error: {e}")
            return None

