    def create_user(self, user_doc, performed_by):
        # Email validation
        """function create_user - TODO: add description.
        Generated: 2026-08-01T21:49:18.295802Z
        """
        if not self.validate_email_format(user_doc["email"]):
            raise RuntimeError("Invalid email format.")

        if self.email_exists(user_doc["email"]):
            raise RuntimeError("Email already in use.")

        # Ensure role exists
        role = user_doc.setdefault("role", "viewer")

        # Assign default permissions
        default_perms = self.DEFAULT_ROLE_PERMISSIONS.get(role, [])
        user_doc.setdefault("permissions", default_perms.copy())

        try:
            # Persist the user first; only then emit audit/log events so logs
            # reflect completed state (avoid logging partially-failed operations).
            self.users.insert_one(user_doc)

            self.audit(
                event="user.create",
                performed_by=performed_by,
                target=user_doc.get("username"),
                details={
                    "email": user_doc.get("email"),
                    "role": user_doc.get("role"),
                    "permissions": user_doc.get("permissions"),
                }
            )

            log_event(
                "info",
                "User created",
                by=performed_by,
                target=user_doc.get("username"),
                role=role,
                permissions=",".join(user_doc.get("permissions", []))
            )

        except Exception as e:
            # Log the failure (no sensitive details included) and propagate.
            log_event(
                "error",
                "User creation failed",
                by=performed_by,
                target=user_doc.get("username"),
                error=str(e)
            )
            raise RuntimeError(f"Failed to create user: {e}")

