    def update_permissions(self, user_id, new_permissions, performed_by):
        """function update_permissions - TODO: add description.
        Generated: 2026-08-01T21:49:18.295802Z
        """
        try:
            user = self.users.find_one({"_id": ObjectId(user_id)})
            username = user.get("username") if user else user_id

            old = set(user.get("permissions", []))
            new = set(new_permissions)

            added = new - old
            removed = old - new

            self.users.update_one(
                {"_id": ObjectId(user_id)},
                {"$set": {"permissions": list(new)}}
            )

            log_event(
                "info",
                "Permissions updated",
                by=performed_by,
                target=username,
                added=",".join(added),
                removed=",".join(removed)
            )
            self.audit(
                event="user.update_permissions",
                performed_by=performed_by,
                target=username,
                details={
                    "added": list(added),
                    "removed": list(removed)
                }
            )


        except Exception as e:
            log_event(
                "error",
                "Permission update failed",
                by=performed_by,
                target=user_id,
                error=str(e)
            )
