    def audit(self, event, performed_by, target=None, details=None):
        """Write a sanitized audit document to the `audit_log` collection.

        We sanitize `target` and `details` to avoid persisting secrets, and
        always include a timestamp so entries can be ordered reliably.
        """
        doc = {
            "timestamp": datetime.utcnow(),
            "event": event,
            "performed_by": performed_by,
            "target": _sanitize_audit_value(target, "target"),
            "details": _sanitize_audit_value(details),
        }

        # Insert directly to the audit collection; callers should handle
        # any exceptions from the database layer if they need retries.
        self.audit_log.insert_one(doc)

    def log_event(self, event, performed_by, details=""):
        """Compatibility wrapper: keep older callsites working by forwarding
        to `audit()` which performs the real insert and sanitization.
        """
        return self.audit(event, performed_by, details=details)


